//   transform: translate(-50%,-50%); }
export function cursorGlow(el) {
  if (window.matchMedia("(hover: none), (prefers-reduced-motion: reduce)").matches) { el.remove(); return () => {}; }
  let tx = innerWidth / 2, ty = innerHeight / 2, x = tx, y = ty, raf = 0;
  const onMove = (e) => { tx = e.clientX; ty = e.clientY; };
  const loop = () => {
    x += (tx - x) * 0.08; y += (ty - y) * 0.08;
    el.style.left = x + "px"; el.style.top = y + "px";
    raf = requestAnimationFrame(loop);
  };
  window.addEventListener("pointermove", onMove, { passive: true });
  raf = requestAnimationFrame(loop);
  return () => { cancelAnimationFrame(raf); window.removeEventListener("pointermove", onMove); };
}
```

### 8d. Floating particles (canvas)
**When:** dark heroes (AI/crypto). ≤ 60 particles, one rAF loop, paused when off-screen.

```html
<canvas class="particles" aria-hidden="true"></canvas>
<script>
  (() => {
    if (matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    const canvas = document.querySelector(".particles");
    const ctx = canvas.getContext("2d");
    let w, h, running = false, raf = 0;
    const N = Math.min(60, Math.floor(innerWidth / 24));
    const dots = Array.from({ length: N }, () => ({
      x: Math.random(), y: Math.random(),
      r: 1 + Math.random() * 2,
      vx: (Math.random() - 0.5) * 0.0004, vy: (Math.random() - 0.5) * 0.0004,
    }));
    function resize() { w = canvas.width = canvas.offsetWidth * devicePixelRatio; h = canvas.height = canvas.offsetHeight * devicePixelRatio; }
    function frame() {
      if (!running) return;
      ctx.clearRect(0, 0, w, h);
      ctx.fillStyle = "rgba(192,132,252,.6)";
      for (const d of dots) {
        d.x = (d.x + d.vx + 1) % 1; d.y = (d.y + d.vy + 1) % 1;
        ctx.beginPath(); ctx.arc(d.x * w, d.y * h, d.r * devicePixelRatio, 0, 7); ctx.fill();
      }
      raf = requestAnimationFrame(frame);
    }
    resize();
    addEventListener("resize", resize);
    new IntersectionObserver(([e]) => {
      running = e.isIntersecting;
      if (running) raf = requestAnimationFrame(frame); else cancelAnimationFrame(raf);
    }).observe(canvas);
  })();
</script>
```

